using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace Siderectomy {
 // Explicit test flag only. All saves and deterministic victory fixtures stay in a separate test directory.
 public sealed class DemoProgressionCheck : MonoBehaviour {
  static bool started;string directory;readonly List<string> checks=new List<string>();
  public static void TryStart(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--progression-check");if(started||i<0||i+1>=args.Length)return;started=true;Application.runInBackground=true;var go=new GameObject("ProgressionValidation");DontDestroyOnLoad(go);var test=go.AddComponent<DemoProgressionCheck>();test.directory=args[i+1];Directory.CreateDirectory(test.directory);Application.logMessageReceived+=test.OnLog;test.StartCoroutine(test.Run());}
  void OnLog(string value,string stack,LogType type){if(type!=LogType.Error&&type!=LogType.Exception)return;File.WriteAllText(Path.Combine(directory,"failure.txt"),value+"\n"+stack);Application.Quit(1);}
  void Require(bool value,string text){if(!value)throw new Exception("PROGRESSION_UI: "+text);checks.Add("PASS "+text);}
  static IEnumerator Frame(){yield return null;yield return null;}
  void Click(string name){Canvas.ForceUpdateCanvases();var go=GameObject.Find(name);Require(go!=null,"入口存在 "+name);DemoFlowCheck.Reveal(go);var button=go.GetComponent<Button>();Require(button!=null&&button.interactable,"入口可点击 "+name);var rect=(RectTransform)go.transform;var pointer=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,hits);Require(hits.Count>0&&(hits[0].gameObject==go||hits[0].gameObject.transform.IsChildOf(go.transform)),"入口未被遮挡 "+name);ExecuteEvents.Execute(go,pointer,ExecuteEvents.pointerClickHandler);}
  IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var camera=Camera.main;var canvas=FindObjectOfType<Canvas>();var oldMode=canvas.renderMode;var oldCamera=canvas.worldCamera;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;var target=new RenderTexture(1600,900,24);camera.targetTexture=target;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;var pixels=new Texture2D(1600,900,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,1600,900),0,0);pixels.Apply();File.WriteAllBytes(Path.Combine(directory,name+".png"),pixels.EncodeToPNG());camera.targetTexture=oldTarget;RenderTexture.active=oldActive;canvas.renderMode=oldMode;canvas.worldCamera=oldCamera;Canvas.ForceUpdateCanvases();Destroy(pixels);target.Release();Destroy(target);yield return null;}
  static DemoMissionView View(){return FindObjectOfType<DemoMissionView>();}
  static void VictoryFixture(){var s=View().Simulation;foreach(var b in s.Bodies)b.pop=0;foreach(var ship in s.Ships)ship.done=true;s.SolarReservedPopulation=0;if(s.Level.number==4)s.SolarStoryPhase=4;s.Exposure=999999;s.Entropy=999999;s.CheckEnd();}
  void CheckHeader(int highest){for(int n=1;n<=DemoProgression.LevelCount;n++)Require(GameObject.Find("Level"+n).GetComponent<Button>().interactable==(n<=highest),"局内选关门槛 "+n+" / "+highest);}
  IEnumerator Run(){yield return Frame();Require(FindObjectOfType<DemoFrontMenu>()!=null,"从开始界面进入");Require(GameObject.Find("TitleArtwork")!=null&&GameObject.Find("TitleArtwork").GetComponent<RawImage>().texture!=null,"新标题插画已接入");yield return Capture("01_标题插画");Click("NewProfile");yield return Frame();GameObject.Find("ProfileName").GetComponent<InputField>().text="线性进度验收";Click("ConfirmNewProfile");yield return Frame();string id=DemoSession.Profile.id;
   Require(DemoSession.Profile.highestUnlockedLevel==1&&DemoSession.Profile.completedLevels.Count==0,"新档仅开放第一关");for(int i=1;i<=DemoProgression.LevelCount;i++)Require(GameObject.Find("OfficeLevel"+i).GetComponent<Button>().interactable==(i==1),"办公室锁定 "+i);yield return Capture("02_新档办公室锁定");GameObject.Find("OfficeLevel4").GetComponent<Button>().onClick.Invoke();yield return Frame();Require(FindObjectOfType<OfficeView>()!=null&&DemoSession.Profile.currentLevel==1,"绕过禁用按钮仍不能越级");Click("OfficeLevel1");yield return Frame();CheckHeader(1);var original=View().Simulation;View().LoadLevel(4);Require(View().Simulation==original,"直接加载入口不能越级");bool rejected=false;try{View().RestoreFromSave(new DemoSimulation(DemoLevel.Defaults()[3],DemoRuleBook.Load()).Capture());}catch(InvalidOperationException){rejected=true;}Require(rejected&&View().Simulation==original,"恢复入口不能载入未解锁关卡");yield return Capture("03_第一关局内锁定");
   View().Simulation.Paused=false;View().Simulation.Advance(View().Simulation.Level.limit);yield return Frame();Require(!View().Simulation.Won&&DemoSession.Profile.highestUnlockedLevel==1&&GameObject.Find("NextLevel")==null,"失败不解锁下一关");yield return Capture("04_失败保持锁定");Click("Retry");yield return Frame();VictoryFixture();yield return Frame();Require(View().Simulation.Won&&DemoSession.Profile.highestUnlockedLevel==2&&DemoSession.Profile.completedLevels.SequenceEqual(new[]{1}),"完成第一关解锁第二关，分数不作为门槛");Require(DemoSaveStore.Load(id).highestUnlockedLevel==2,"胜利进度立即落盘");yield return Capture("05_完成第一关解锁第二关");Click("NextLevel");yield return Frame();Require(View().Simulation.Level.number==2,"结果页前往下一关");CheckHeader(2);
   View().OpenPauseMenu();yield return Frame();Click("AbandonSimulation");yield return Frame();Require(GameObject.Find("OfficeLevel1").GetComponent<Button>().interactable&&GameObject.Find("OfficeLevel2").GetComponent<Button>().interactable&&!GameObject.Find("OfficeLevel3").GetComponent<Button>().interactable,"办公室显示累计解锁");yield return Capture("06_办公室第二关可进入");Click("OfficeLevel1");yield return Frame();VictoryFixture();yield return Frame();Require(DemoSession.Profile.highestUnlockedLevel==2&&DemoSession.Profile.completedLevels.Count==1,"重玩第一关不重复解锁或跳关");Click("Inspect");yield return Frame();View().OpenPauseMenu();yield return Frame();Click("SaveSimulation");yield return Frame();Require(!DemoSession.Profile.hasCheckpoint&&DemoSession.Profile.currentLevel==2,"通关后保存退出保留下一关位置，不保存已完成现场");Click("OfficeLevel2");yield return Frame();View().Simulation.Time=9;View().OpenPauseMenu();yield return Frame();Click("SaveSimulation");yield return Frame();Require(DemoSession.Profile.hasCheckpoint&&DemoSession.Profile.highestUnlockedLevel==2,"保存现场保留关卡解锁");Click("OfficeMainMenu");yield return Frame();Click("ContinueGame");yield return Frame();Click("Load_"+id);yield return Frame();Require(View().Simulation.Level.number==2&&View().Simulation.Paused&&Math.Abs(View().Simulation.Time-9)<1e-7,"读档恢复第二关现场与暂停状态");Require(DemoSession.Profile.highestUnlockedLevel==2&&!GameObject.Find("Level3").GetComponent<Button>().interactable,"读档没有开放第三关");yield return Capture("07_第二关存档恢复");
   VictoryFixture();yield return Frame();Require(!DemoSession.Profile.hasCheckpoint&&DemoSession.Profile.highestUnlockedLevel==3,"第二关完成后清理现场并解锁第三关");Click("Inspect");yield return Frame();View().OpenPauseMenu();yield return Frame();Click("AbandonSimulation");yield return Frame();Require(DemoSession.Profile.currentLevel==3&&!DemoSession.Profile.hasCheckpoint,"通关后放弃退出保留下一关位置");Click("OfficeLevel3");yield return Frame();VictoryFixture();yield return Frame();Require(DemoSession.Profile.highestUnlockedLevel==4,"第三关完成解锁第四关");Click("NextLevel");yield return Frame();VictoryFixture();yield return Frame();Require(DemoSession.Profile.highestUnlockedLevel==5&&GameObject.Find("NextLevel")!=null,"第四关完成继续解锁第五关");CheckHeader(5);Click("NextLevel");yield return Frame();Require(View().Simulation.Level.number==5,"第五关入口可用");VictoryFixture();yield return Frame();Require(DemoSession.Profile.highestUnlockedLevel==6,"第五关完成解锁第六关");Click("NextLevel");yield return Frame();Require(View().Simulation.Level.number==6,"第六关入口可用");VictoryFixture();yield return Frame();Require(DemoSession.Profile.highestUnlockedLevel==6&&DemoSession.Profile.completedLevels.SequenceEqual(new[]{1,2,3,4,5,6})&&GameObject.Find("NextLevel")==null,"末关完成不产生不存在的下一关");yield return Capture("08_六关全部完成");Click("Inspect");yield return Frame();View().OpenPauseMenu();yield return Frame();Click("AbandonSimulation");yield return Frame();Click("OfficeMainMenu");yield return Frame();Click("NewProfile");yield return Frame();GameObject.Find("ProfileName").GetComponent<InputField>().text="独立的新档";Click("ConfirmNewProfile");yield return Frame();Require(DemoSession.Profile.highestUnlockedLevel==1&&DemoSession.Profile.id!=id,"新档不继承另一档案的解锁");Require(DemoSaveStore.Load(id).highestUnlockedLevel==6,"另一档案的进度仍保存");
   File.WriteAllText(Path.Combine(directory,"progression-pass.txt"),string.Join("\n",checks)+"\n使用独立测试存档；通关使用确定性目标完成夹具，仅验证进度与交互，不代表六关真实手动难度。\n");Application.logMessageReceived-=OnLog;Application.Quit(0);
  }
 }
}
